import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  spring,
  interpolate,
} from '../remotionShim';
// Font Loading
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');
const { fontFamily: interFamily } = loadInter();



export type InstagramUnfollowProps = Record<string, any>;

const InstagramUnfollow: React.FC<InstagramUnfollowProps> = ({
  backgroundColor = "#ffffff",
  transparentBackground = false,
  durationInSeconds = 4,
  initialButtonText = "Following",
  finalButtonText = "Follow",
  initialButtonColor = "#efefef",
  initialTextColor = "#000000",
  finalButtonColor = "#0095f6",
  finalTextColor = "#ffffff",
  cursorColor = "#000000",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground
    ? `${backgroundColor}00`
    : backgroundColor;

  // Timeline Markers
  const entranceDuration = fps; // 1 second to enter
  const clickFrame = Math.floor(fps * 1.5); // Click happens at 1.5s
  const exitStartFrame = clickFrame + 15; // Start leaving shortly after click

  // Cursor Movement Dynamics
  const moveIn = spring({
    frame,
    fps,
    config: { damping: 14, mass: 0.8 },
    durationInFrames: entranceDuration,
  });

  const moveOut = spring({
    frame: frame - exitStartFrame,
    fps,
    config: { damping: 14, mass: 0.8 },
  });

  // Calculate Cursor Position
  // Starts off-screen bottom right, moves to center (button), then exits bottom right
  const startX = width / 2 + width * 0.4;
  const startY = height / 2 + height * 0.4;
  const targetX = width / 2;
  const targetY = height / 2;

  const cursorX =
    interpolate(moveIn, [0, 1], [startX, targetX]) +
    interpolate(moveOut, [0, 1], [0, startX - targetX]);

  const cursorY =
    interpolate(moveIn, [0, 1], [startY, targetY]) +
    interpolate(moveOut, [0, 1], [0, startY - targetY]);

  // Interaction Scaling (The "Click")
  const cursorClickScale = interpolate(
    frame,
    [clickFrame, clickFrame + 3, clickFrame + 8],
    [1, 0.85, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  const buttonClickScale = interpolate(
    frame,
    [clickFrame, clickFrame + 3, clickFrame + 8],
    [1, 0.92, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // State Management (Hard cut right at the nadir of the button press)
  const isClicked = frame >= clickFrame + 3;
  const currentBg = isClicked ? finalButtonColor : initialButtonColor;
  const currentTextCol = isClicked ? finalTextColor : initialTextColor;
  const currentText = isClicked ? finalButtonText : initialButtonText;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: interFamily,
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
      }}
    >
      {/* Button Wrapper */}
      <div
        style={{
          transform: `scale(${buttonClickScale})`,
          transformOrigin: "center center",
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
        }}
      >
        {/* The Button */}
        <div
          style={{
            backgroundColor: currentBg,
            color: currentTextCol,
            padding: "16px 0",
            borderRadius: "12px",
            fontWeight: 600,
            fontSize: "32px",
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
            width: "280px", // Fixed width prevents layout shifts on text change
            transition: "none",
            boxShadow: "0 2px 8px rgba(0,0,0,0.05)",
            userSelect: "none",
          }}
        >
          {currentText}
        </div>
      </div>

      {/* Cursor */}
      <div
        style={{
          position: "absolute",
          left: 0,
          top: 0,
          // Offset by -6,-6 to align the visual tip of the SVG path (M6 6) precisely to the target coordinate
          transform: `translate(${cursorX - 6}px, ${cursorY - 6}px) scale(${cursorClickScale})`,
          transformOrigin: "6px 6px",
          zIndex: 10,
          pointerEvents: "none",
          filter: "drop-shadow(0px 4px 6px rgba(0,0,0,0.2))",
        }}
      >
        <svg
          width="64"
          height="64"
          viewBox="0 0 32 32"
          fill="none"
          xmlns="http://www.w3.org/2000/svg"
        >
          <path
            d="M6 6L23 12.5L15 15L12.5 23L6 6Z"
            fill={cursorColor}
            stroke="white"
            strokeWidth="1.5"
            strokeLinejoin="round"
          />
        </svg>
      </div>
    </AbsoluteFill>
  );
};

export default InstagramUnfollow;